using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Grasshopper.Kernel;

namespace BenchPlugin
{
    public class AsyncStatsComponent : GH_Component
    {
        private CancellationTokenSource _cts;
        private List<double> _input;
        private (double Mean, double StdDev)? _result;
        private readonly object _lock = new object();

        public AsyncStatsComponent()
            : base("Async Stats", "AStats", "Computes mean and standard deviation asynchronously", "Bench", "Data")
        {
        }

        public override Guid ComponentGuid => new Guid("bf5c2a6e-71b8-4d3b-e475-bc8b2a6d3f54");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddNumberParameter("Values", "V", "Numbers to analyse", GH_ParamAccess.list);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Mean", "M", "Arithmetic mean", GH_ParamAccess.item);
            pManager.AddNumberParameter("StdDev", "S", "Population standard deviation", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var values = new List<double>();
            if (!DA.GetDataList(0, values) || values.Count == 0)
            {
                Cancel();
                return;
            }

            (double Mean, double StdDev)? ready = null;
            lock (_lock)
            {
                if (_input != null && _input.SequenceEqual(values))
                {
                    ready = _result;
                }
                else
                {
                    _cts?.Cancel();
                    _cts = new CancellationTokenSource();
                    _input = values;
                    _result = null;
                    Start(values, _cts.Token);
                }
            }

            if (ready.HasValue)
            {
                DA.SetData(0, ready.Value.Mean);
                DA.SetData(1, ready.Value.StdDev);
            }
        }

        private void Cancel()
        {
            lock (_lock)
            {
                _cts?.Cancel();
                _cts = null;
                _input = null;
                _result = null;
            }
        }

        private void Start(List<double> values, CancellationToken token)
        {
            Task.Run(() =>
            {
                double mean = values.Average();
                token.ThrowIfCancellationRequested();
                double variance = values.Sum(v => (v - mean) * (v - mean)) / values.Count;
                token.ThrowIfCancellationRequested();
                return (mean, Math.Sqrt(variance));
            }, token).ContinueWith(t =>
            {
                if (t.IsCanceled || t.IsFaulted || token.IsCancellationRequested) return;
                lock (_lock)
                {
                    if (token.IsCancellationRequested) return;
                    _result = t.Result;
                }
                var doc = OnPingDocument();
                doc?.ScheduleSolution(5, d => ExpireSolution(false));
            }, TaskScheduler.Default);
        }
    }
}
